// Costruisce la richiesta di estrazione per Claude a partire dal file scaricato dallo storage.
const meta = $('Avvia elaborazione').first().json;
const buf = await this.helpers.getBinaryDataBuffer(0, 'data');
const ext = String(meta.file_path || '').split('.').pop().toLowerCase();
const mime = meta.mime || 'application/pdf';

let blocco;
if (ext === 'xml' || mime.includes('xml')) {
  blocco = { type: 'text', text: 'Documento XML (FatturaPA o simile):\n' + buf.toString('utf8').slice(0, 300000) };
} else if (mime === 'application/pdf') {
  blocco = { type: 'document', source: { type: 'base64', media_type: 'application/pdf', data: buf.toString('base64') } };
} else if (mime.startsWith('image/')) {
  blocco = { type: 'image', source: { type: 'base64', media_type: mime, data: buf.toString('base64') } };
} else {
  throw new Error('Formato non supportato: ' + mime);
}

const SYSTEM = "Sei un sistema di Document Intelligence di livello enterprise specializzato nella contabilità cross-border (Italia, Francia, Monaco, Svizzera) per la ristorazione di lusso. Estrai con precisione i dati da documenti commerciali multilingue (fatture, DDT, note di credito in italiano, francese, tedesco o inglese, anche FatturaPA XML).\n\nREGOLE RIGIDE\n1. Restituisci ESCLUSIVAMENTE un oggetto JSON valido: nessun testo introduttivo, nessun commento, nessun blocco markdown.\n2. Se un dato non è presente usa null. Non inventare e non dedurre valori che il documento non riporta.\n3. Date nel formato YYYY-MM-DD. Numeri come numeri JSON con il punto decimale.\n4. Valuta: codice ISO del documento (EUR, CHF, USD…). Non convertire gli importi.\n5. Paese del fornitore: IT, FR, MC, CH o altro codice ISO. Per FR/MC inserisci SIRET/SIREN in codice_identificativo_estero.\n6. Estrai TUTTE le righe con un prezzo, nell'ordine del documento, comprese spese di trasporto, cauzioni e imballi.\n7. unita_misura è l'unità a cui si riferisce prezzo_unitario, normalizzata in: kg, g, lt, cl, ml, pz, conf, mt.\n8. prezzo_unitario è il prezzo per unità di misura PRIMA degli sconti di riga; lo sconto va in sconto_percentuale. totale_riga è l'imponibile della riga.\n9. descrizione_originale è il testo esatto del documento. descrizione_articolo è il nome in italiano, pulito e specifico: conserva taglio, razza, varietà, origine, denominazione (DOP/IGP/AOC), stagionatura, annata e formato della confezione; elimina codici interni, lotti e date di scadenza. Esempio: \"Filet de bœuf Charolais VBF\" → \"Filetto di manzo Charolais\".\n10. peso_netto_kg: peso netto TOTALE della riga in kg, solo se il documento lo riporta e l'unità di vendita non è già il peso (esempio: 2 pz, peso 2,4 kg → 2.4). Altrimenti null.\n11. contenuto_per_unita e unita_contenuto: quando l'articolo è venduto a pezzo o confezione e il documento ne indica il contenuto, riporta quanto contiene UNA unità di vendita, in kg, lt o pz. Esempi: \"cartone 6 × 1 L\" → 6 e \"lt\"; \"bottiglia 75 cl\" → 0.75 e \"lt\"; \"vaschetta 500 g\" → 0.5 e \"kg\"; \"cassa 12 pz\" → 12 e \"pz\". Altrimenti null.\n\nSTRUTTURA\n{\"documento\":{\"tipo\":\"Fattura|DDT|Nota di Credito|Altro\",\"numero_documento\":null,\"data_documento\":null,\"codice_valuta\":\"EUR\"},\n\"fornitore\":{\"ragione_sociale\":\"\",\"partita_iva_o_estera\":null,\"paese\":\"IT\",\"codice_identificativo_estero\":null},\n\"cliente\":{\"ragione_sociale\":null,\"partita_iva\":null},\n\"totali\":{\"imponibile\":0,\"iva\":0,\"totale_documento\":0,\"valuta\":\"EUR\"},\n\"articoli\":[{\"codice_articolo_fornitore\":null,\"descrizione_originale\":\"\",\"descrizione_articolo\":\"\",\"quantita\":0,\"unita_misura\":\"kg\",\"prezzo_unitario\":0,\"sconto_percentuale\":null,\"totale_riga\":0,\"aliquota_iva_percentuale\":null,\"peso_netto_kg\":null,\"contenuto_per_unita\":null,\"unita_contenuto\":null}]}";

return [{ json: {
  documento_id: meta.documento_id,
  claudeRequest: {
    model: 'claude-sonnet-5-5',
    max_tokens: 16000,
    system: SYSTEM,
    messages: [{ role: 'user', content: [blocco, { type: 'text', text: 'Analizza il documento allegato ed estrai i dati seguendo rigorosamente la struttura. Solo JSON.' }] }]
  }
} }];

// Valida la risposta di Claude e normalizza numeri, date e unità di misura.
const res = $input.first().json;
if (res.stop_reason === 'max_tokens') throw new Error('Documento troppo lungo: dividilo in più file e riprova');
const text = (res.content || []).filter(c => c.type === 'text').map(c => c.text).join('').trim();
if (!text) throw new Error('Il modello non ha restituito dati');
const raw = text.replace(/^```(?:json)?\s*/i, '').replace(/```\s*$/, '');
const s = raw.indexOf('{'), e = raw.lastIndexOf('}');
if (s < 0 || e < 0) throw new Error('Risposta del modello non interpretabile');
let data;
try { data = JSON.parse(raw.slice(s, e + 1)); } catch (err) { throw new Error('Risposta del modello non valida: ' + err.message); }

const num = v => {
  if (v === null || v === undefined || v === '') return null;
  if (typeof v === 'number') return Number.isFinite(v) ? v : null;
  let t = String(v).replace(/[^0-9,.\-]/g, '');
  if (t.includes(',') && t.includes('.')) t = t.lastIndexOf(',') > t.lastIndexOf('.') ? t.replace(/\./g, '').replace(',', '.') : t.replace(/,/g, '');
  else if (t.includes(',')) t = t.replace(',', '.');
  const n = parseFloat(t);
  return Number.isFinite(n) ? n : null;
};
const UM = { kg: 'kg', kilo: 'kg', kgs: 'kg', g: 'g', gr: 'g', grammi: 'g', lt: 'lt', l: 'lt', litre: 'lt', litro: 'lt', litri: 'lt', cl: 'cl', ml: 'ml', pz: 'pz', pc: 'pz', pce: 'pz', pcs: 'pz', u: 'pz', un: 'pz', unite: 'pz', 'unité': 'pz', nr: 'pz', st: 'pz', stk: 'pz', conf: 'conf', cf: 'conf', ct: 'conf', crt: 'conf', colis: 'conf', carton: 'conf', mt: 'mt', m: 'mt' };
const um = v => { const k = String(v || '').toLowerCase().replace(/\./g, '').trim(); return UM[k] || (k || null); };
const date = v => (v && /^\d{4}-\d{2}-\d{2}/.test(v)) ? String(v).slice(0, 10) : null;

const doc = data.documento || {};
doc.tipo = ['Fattura', 'DDT', 'Nota di Credito', 'Altro'].includes(doc.tipo) ? doc.tipo : 'Altro';
doc.data_documento = date(doc.data_documento);
doc.codice_valuta = String(doc.codice_valuta || (data.totali || {}).valuta || 'EUR').toUpperCase().slice(0, 3);

const forn = data.fornitore || {};
if (!forn.ragione_sociale) throw new Error('Fornitore non riconosciuto nel documento');
forn.paese = forn.paese ? String(forn.paese).toUpperCase().slice(0, 2) : null;

const tot = data.totali || {};
['imponibile', 'iva', 'totale_documento'].forEach(k => { tot[k] = num(tot[k]); });
tot.valuta = doc.codice_valuta;

const articoli = (data.articoli || []).map(a => {
  const uc = um(a.unita_contenuto);
  return {
    codice_articolo_fornitore: a.codice_articolo_fornitore ? String(a.codice_articolo_fornitore).trim() : null,
    descrizione_originale: a.descrizione_originale || a.descrizione_articolo || null,
    descrizione_articolo: a.descrizione_articolo || a.descrizione_originale || null,
    quantita: num(a.quantita),
    unita_misura: um(a.unita_misura),
    prezzo_unitario: num(a.prezzo_unitario),
    sconto_percentuale: num(a.sconto_percentuale),
    totale_riga: num(a.totale_riga),
    aliquota_iva_percentuale: num(a.aliquota_iva_percentuale),
    peso_netto_kg: num(a.peso_netto_kg),
    contenuto_per_unita: num(a.contenuto_per_unita),
    unita_contenuto: ['kg', 'g', 'lt', 'cl', 'ml', 'pz'].includes(uc) ? uc : null
  };
}).filter(a => a.descrizione_articolo && a.prezzo_unitario !== null);

return [{ json: {
  p_documento_id: $('Avvia elaborazione').first().json.documento_id,
  payload: { documento: doc, fornitore: forn, cliente: data.cliente || {}, totali: tot, articoli }
} }];

// Legge le decisioni del giudice. In caso di risposta non valida non blocca il documento:
// le righe restano "da abbinare" e finiscono nella coda di validazione.
let decisioni = [];
try {
  const res = $input.first().json;
  const text = (res.content || []).filter(c => c.type === 'text').map(c => c.text).join('').trim();
  const raw = text.replace(/^```(?:json)?\s*/i, '').replace(/```\s*$/, '');
  const data = JSON.parse(raw.slice(raw.indexOf('{'), raw.lastIndexOf('}') + 1));
  if (Array.isArray(data.decisioni)) decisioni = data.decisioni;
} catch (err) {
  decisioni = [];
}
return [{ json: {
  p_documento_id: $('Ricevi documento').first().json.body.documento_id,
  p_decisioni: decisioni
} }];
